  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import hotel.rooms.RoomType;
  5	import java.math.BigDecimal;
  6	import java.math.RoundingMode;
  7	import java.time.DayOfWeek;
  8	import java.time.LocalDate;
  9	import java.time.Month;
 10	import java.util.Map;
 11	
 12	/**
 13	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 14	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 15	 * (half-even) at every step.
 16	 */
 17	public final class PriceCalculator {
 18	
 19	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 20	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 21	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 22	
 23	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 24	            "TECNOSUL", new BigDecimal("0.12"),
 25	            "AGROVALE", new BigDecimal("0.18"),
 26	            "FARMAVIDA", new BigDecimal("0.25"));
 27	
 28	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 29	            RoomType.STANDARD, new BigDecimal("520.00"),
 30	            RoomType.DELUXE, new BigDecimal("820.00"),
 31	            RoomType.SUITE, new BigDecimal("1200.00"));
 32	
 33	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 34	        int nights = 0;
 35	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 36	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 37	            subtotal = subtotal.add(nightPrice(room, night));
 38	            nights++;
 39	        }
 40	
 41	        BigDecimal discount;
 42	        BigDecimal total;
 43	
 44	        switch (ratePlan) {
 45	            case STANDARD:
 46	                discount = cents(BigDecimal.ZERO);
 47	                total = subtotal;
 48	                break;
 49	            case NON_REFUNDABLE:
 50	                discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 51	                total = subtotal.subtract(discount);
 52	                break;
 53	            case CORPORATE:
 54	                if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
 55	                    throw new HotelException(ErrorCode.INVALID_REQUEST,
 56	                            "corporate rate plan requires a valid company code");
 57	                }
 58	                BigDecimal corporateDiscount = CORPORATE_DISCOUNTS.get(companyCode);
 59	                discount = cents(subtotal.multiply(corporateDiscount));
 60	                total = subtotal.subtract(discount);
 61	                break;
 62	            case WEEKEND_PACKAGE:
 63	                if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY
 64	                        || checkOut.getDayOfWeek() != DayOfWeek.SUNDAY
 65	                        || nights != 2) {
 66	                    throw new HotelException(ErrorCode.INVALID_REQUEST,
 67	                            "weekend package requires check-in on Friday and check-out on Sunday (2 nights)");
 68	                }
 69	                BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.type());
 70	                subtotal = packagePrice;
 71	                discount = cents(BigDecimal.ZERO);
 72	                total = packagePrice;
 73	                break;
 74	            case LONG_STAY:
 75	                if (nights < 7) {
 76	                    throw new HotelException(ErrorCode.INVALID_REQUEST,
 77	                            "long stay rate plan requires at least 7 nights");
 78	                }
 79	                discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 80	                total = subtotal.subtract(discount);
 81	                break;
 82	            default:
 83	                discount = cents(BigDecimal.ZERO);
 84	                total = subtotal;
 85	        }
 86	
 87	        return new Price(nights, subtotal, discount, total);
 88	    }
 89	
 90	    BigDecimal nightPrice(Room room, LocalDate night) {
 91	        BigDecimal nightlyRate = room.nightlyRate();
 92	        if (isHighSeason(night)) {
 93	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 94	        }
 95	        return cents(nightlyRate);
 96	    }
 97	
